/* AIPL Function: canonicalizeGraphDepsOnDisk */
__attribute__((hot)) AiplVal aipl_fn_canonicalizeGraphDepsOnDisk(AiplVal v_filePath, AiplVal v_moduleName, AiplVal v_graphIn) {
  AiplVal v_graph = aipl_nil();
  AiplVal v_anyDepCanon = aipl_nil();
  AiplVal v_gmi = aipl_nil();
  AiplVal v_mPath = aipl_nil();
  AiplVal v_cDep = aipl_nil();
  v_graph = v_graphIn;
  v_anyDepCanon = aipl_bool(false);
  v_gmi = aipl_int(0LL);
  while (aipl_truthy(aipl_lt(v_gmi, aipl_member_get(aipl_member_get_idx(v_graph, 1, "modules"), "len")))) {
    v_mPath = aipl_member_get_idx(aipl_index_get(aipl_member_get_idx(v_graph, 1, "modules"), v_gmi), 0, "path");
    if (aipl_truthy((aipl_truthy((aipl_truthy((aipl_truthy((aipl_truthy((aipl_truthy(aipl_gt(aipl_member_get(v_mPath, "len"), aipl_int(0LL))) ? aipl_bool(aipl_truthy(aipl_neq(v_mPath, v_filePath))) : aipl_bool(false))) ? aipl_bool(aipl_truthy(aipl_str_ends_with(v_mPath, aipl_str_n(".aipl", 5)))) : aipl_bool(false))) ? aipl_bool(aipl_truthy(aipl_not(aipl_str_starts_with(v_mPath, aipl_str_n("std/", 4))))) : aipl_bool(false))) ? aipl_bool(aipl_truthy(aipl_not(aipl_contains(v_mPath, aipl_str_n("/std/", 5))))) : aipl_bool(false))) ? aipl_bool(aipl_truthy(aipl_fn_fileExists(v_mPath))) : aipl_bool(false)))) {
      v_cDep = aipl_fn_canonicalizeAiplFileOnDisk(v_mPath);
      if (aipl_truthy(aipl_neq(v_cDep, aipl_member_get_idx(aipl_index_get(aipl_member_get_idx(v_graph, 1, "modules"), v_gmi), 5, "source")))) {
        v_anyDepCanon = aipl_bool(true);
      }
    }
    aipl_inc_int(&v_gmi, 1LL);
  }
  if (aipl_truthy(v_anyDepCanon)) {
    v_graph = aipl_fn_resolveImports(v_filePath, aipl_fn_arenaNew(v_moduleName));
  }
  return v_graph;
}

