    aipl_println(aipl_str_n("  - CLI & I/O: JSON-RPC 2.0 dispatcher, declarative CliApp argument parsing, streaming pipes", 92));
    aipl_println(aipl_str_n("  - Math & DSP: 3D vector & matrix affine transforms, quaternions, Cooley-Tukey radix-2 FFT", 91));
    aipl_println(aipl_str_n("  - Algorithms & Collections: Dijkstra shortest path, Kruskal MST, spatial 2D grid hashing", 90));
    aipl_println(aipl_str_n("  - Security & Crypto: ChaCha20-Poly1305 AEAD, SHA-256 / BLAKE3 hashes, TLS handshake probe", 91));
    aipl_println(aipl_str_n("  - Systems: Work-stealing Chase-Lev deque, lock-free ringbuffers, bump arena allocators", 88));
    aipl_println(aipl_str_n("  - Graphics & Canvas: Fixed-timestep accumulator, 2D sprite batcher, 3D frustum culler", 87));
    aipl_println(aipl_str_n("  - Game Architecture: Generational entity arena, state machine transitions, save engine v3", 91));
    aipl_println(aipl_str(""));
    aipl_println(aipl_str_n("Search recipes with: aipl help cookbook <query>", 47));
