/* AIPL Function: runParallelCommands */
__attribute__((hot)) AiplVal aipl_fn_runParallelCommands(AiplVal v_cmds, AiplVal v_maxJobs) {
  AiplVal v_results = aipl_nil();
  AiplVal v_fallbackCodes = aipl_nil();
  AiplVal v_ci = aipl_nil();
  AiplVal v_cmdStr = aipl_nil();
  AiplVal v_res = aipl_nil();
  AiplVal v_code = aipl_nil();
  if (aipl_truthy(aipl_eq(aipl_member_get(v_cmds, "len"), aipl_int(0LL)))) {
    return aipl_array_new(NULL, 0);
  }
  v_results = aipl_rt_exec_parallel(v_cmds, v_maxJobs);
  if (aipl_truthy(aipl_eq(aipl_member_get(v_results, "len"), aipl_member_get(v_cmds, "len")))) {
    return v_results;
  }
  v_fallbackCodes = aipl_array_new(NULL, 0);
  v_ci = aipl_int(0LL);
  while (aipl_truthy(aipl_lt(v_ci, aipl_member_get(v_cmds, "len")))) {
    v_cmdStr = aipl_index_get(v_cmds, v_ci);
    v_res = aipl_fn_execCommand(aipl_str_n("sh", 2), aipl_array_new((AiplVal[]){ aipl_str_n("-c", 2), v_cmdStr }, 2));
    v_code = (aipl_truthy(aipl_res_is_ok(v_res)) ? aipl_member_get_idx(aipl_unwrap(v_res), 2, "status") : aipl_int(1LL));
    (aipl_array_push(v_fallbackCodes, v_code), aipl_nil());
    aipl_inc_int(&v_ci, 1LL);
  }
  return v_fallbackCodes;
}

/* AIPL Function: crc32 */
AiplVal aipl_fn_crc32(AiplVal v_data) {
  return aipl_rt_crc32(v_data);
}

