  (aipl_array_push(v_lines, aipl_str_n("- UFCS Collections: `arr.map(x => x * 2)`, `arr.filter(...)`, `arr.fold(0, (a, b) => a + b)`, `map.set(k, v)`, `map.get(k)`, `map.has(k)`, `map.delete(k)`.", 155)), aipl_nil());
  (aipl_array_push(v_lines, aipl_str_n("- CLI: `aipl run <file.aipl>`, `aipl test <file_or_dir>`, `aipl verify <file.aipl> [--json] [--stream-prefix]`, `aipl wire <file.aipl> <symbol> <replacement.aipl>`.", 164)), aipl_nil());
