static const size_t AIPL_EMBEDDED_SOURCE_LEN = 1548792;

int main(int argc, char** argv) {
  (void)AIPL_EMBEDDED_SOURCE_LEN;
  struct rlimit rl;
  if (getrlimit(RLIMIT_STACK, &rl) == 0 && rl.rlim_cur < 67108864ULL) {
    rl.rlim_cur = 67108864ULL;
    setrlimit(RLIMIT_STACK, &rl);
  }
  g_aipl_argc = argc;
  g_aipl_argv = argv;
  aipl_rt_init_globals();
  AiplVal mainRes = aipl_fn_main();
  if (mainRes.kind == AIPL_INT) {
    return (int)mainRes.i;
  }
  if (mainRes.kind == AIPL_RES_ERR) {
    AiplVal errVal = aipl_unwrap_err(mainRes);
    fprintf(stderr, "%s\n", aipl_to_str(errVal).s ? aipl_to_str(errVal).s : "");
    return 1;
  }
  if (mainRes.kind == AIPL_OPT_NONE) {
    return 1;
  }
  if (mainRes.kind == AIPL_RES_OK || mainRes.kind == AIPL_OPT_SOME) {
    AiplVal inner = aipl_unwrap(mainRes);
    if (inner.kind == AIPL_INT) {
      return (int)inner.i;
    }
  }
  return 0;
}